package com.fixmer.mared.technology.workspace;
import com.fixmer.genesis.technology.workspace.*;import net.minecraft.client.Minecraft;import net.neoforged.neoforge.network.PacketDistributor;import java.util.*;import java.util.function.Consumer;
/** One request per screen session, pinned to its actual connection. Mutations are never automatically replayed. */
public final class WorkspaceClient112 {
 private final Object connection=Minecraft.getInstance().getConnection();private final Consumer<WorkspacePayloads112.Response> sink=p->Minecraft.getInstance().execute(()->receive(p));private WorkspaceWire112.Request pending;private Consumer<Map<String,String>> callback;private long sent;private boolean attached;public String result="IDLE";
 public void attach(){attached=true;WorkspacePayloads112.clientSink=sink;}
 public void detach(){attached=false;if(WorkspacePayloads112.clientSink==sink)WorkspacePayloads112.clientSink=p->{};if(pending!=null)result="UNKNOWN";pending=null;callback=null;}
 public boolean connected(){var c=Minecraft.getInstance().getConnection();return c!=null&&c==connection&&c.hasChannel(WorkspacePayloads112.Request.TYPE.id());}public boolean busy(){return pending!=null;}
 public void tick(){if(pending!=null&&(!connected()||System.nanoTime()-sent>8_000_000_000L)){pending=null;callback=null;result=connected()?"UNKNOWN":"DISCONNECTED";}}
 public void send(WorkspaceWire112.Request q,Consumer<Map<String,String>> done){tick();if(!attached||!connected()){result="DISCONNECTED";return;}if(pending!=null){result="BUSY";return;}try{byte[] bytes=WorkspaceWire112.encode(q);pending=q;callback=done;sent=System.nanoTime();result="WAITING";PacketDistributor.sendToServer(new WorkspacePayloads112.Request(bytes));}catch(Exception bad){pending=null;callback=null;result="INVALID";}}
 private void receive(WorkspacePayloads112.Response response){if(!attached||!connected()||pending==null)return;Map<String,String> d;try{d=WorkspaceWire112.decode(response.bytes());if(!pending.request().toString().equals(d.get("request")))return;if(d.containsKey("project")&&!pending.operation().equals("CREATE")&&!pending.project().equals(d.get("project")))throw new IllegalArgumentException();}catch(Exception bad){pending=null;callback=null;result="INVALID";return;}var done=callback;pending=null;callback=null;result=d.getOrDefault("result","INVALID");try{if(done!=null)done.accept(d);}catch(RuntimeException bad){result="INVALID";com.fixmer.mared.Mared.LOGGER.warn("[Workspace112] Response handler failed",bad);}}
 public static WorkspaceWire112.Request request(String op,String project,String path,String file,String text,long revision,long projectRevision,String target,String role,String other){return new WorkspaceWire112.Request(UUID.randomUUID(),op,project,path,file,text,revision,projectRevision,target,role,other);}
}
